import os
import random
import numpy as np
import torch


class Config:
    """
    Central configuration for the Technosignature Detection project.
    Contains file paths, hyperparameters, and hardware settings.
    """

    # --------------------------------------------------------------------------
    # Directory and File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"
    SUBMISSION_DIR = "./submission"

    # Metadata Paths (Generated by the provided metadata script)
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Output Paths
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Cache Directory for deterministic data processing (Idea 1 specific)
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_1")

    # --------------------------------------------------------------------------
    # Data Specifications
    # --------------------------------------------------------------------------
    # Input data is (6, 273, 256) -> (Cadence Positions, Frequency, Time)
    # Modified to 1 channel of vertically stacked panels (Cite solution_lesson_node_00004)
    NUM_CHANNELS = 1
    HEIGHT = 1638  # 6 * 273
    WIDTH = 256

    # --------------------------------------------------------------------------
    # Model & Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 16  # Reduced for larger input image size
    LEARNING_RATE = 1e-4  # Lower LR for fine-tuning pretrained model (Cite solution_lesson_node_00007)
    EPOCHS = 15  # Maximum training epochs
    PATIENCE = 3  # Early stopping patience

    # --------------------------------------------------------------------------
    # Hardware & Compute
    # --------------------------------------------------------------------------
    NUM_WORKERS = 4  # Suitable for 12 vCPUs
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # --------------------------------------------------------------------------
    # Debugging / Development
    # --------------------------------------------------------------------------
    # Set DEBUG to True to train on a small subset of data for quick verification
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 1000

    @classmethod
    def setup(cls):
        """Creates necessary writable directories if they don't exist."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)


def set_seed(seed=42):
    """
    Sets the random seed for Python, NumPy, and PyTorch to ensure reproducibility.

    Args:
        seed (int): The seed value to use.
    """
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

    if torch.cuda.is_available():
        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)
        # Enforce deterministic algorithms
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

    os.environ["PYTHONHASHSEED"] = str(seed)


# Initialize directories on module import
Config.setup()
